```python
import functools
import logging
import random
import time

logger = logging.getLogger(__name__)


def retry(
    attempts=3,
    delay=1.0,
    backoff=2.0,
    max_delay=None,
    jitter=False,
    exceptions=(Exception,),
):
    """Run a failing function again, stretching the pause out on each pass.

    attempts:   how many calls to make altogether, the first one included.
    delay:      seconds to hold off before the second try.
    backoff:    the factor applied to the pause after every failure.
    max_delay:  optional cap on how long a single pause may run.
    jitter:     when on, sleep for a random stretch in [0, delay) rather than
                the full delay, keeping callers from retrying in lockstep.
    exceptions: exception class, or tuple of classes, that warrants a retry;
                everything else is raised immediately.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            current = delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        raise
                    wait = random.uniform(0, current) if jitter else current
                    logger.warning(
                        "%s failed on attempt %d/%d (%s); retrying in %.2fs",
                        func.__name__, attempt, attempts, exc, wait,
                    )
                    time.sleep(wait)
                    current *= backoff
                    if max_delay is not None:
                        current = min(current, max_delay)

        return wrapper

    return decorator
```

Usage:

```python
@retry(attempts=5, delay=0.5, backoff=2, max_delay=10, jitter=True,
       exceptions=(ConnectionError, TimeoutError))
def fetch(url):
    ...
```

Whatever the final try raised is what reaches the caller, traceback untouched — the true error, with nothing wrapped around it. Pauses run 0.5s, 1s, 2s, 4s, never above `max_delay`.

