import threading
import time
from collections import OrderedDict


class LRUCache:
    """A thread-safe, fixed-capacity LRU cache with optional per-entry TTL."""

    def __init__(self, capacity, default_ttl=None, timer=time.monotonic):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if default_ttl is not None and default_ttl <= 0:
            raise ValueError("default_ttl must be positive or None")
        self.capacity = capacity
        self.default_ttl = default_ttl
        self._timer = timer
        self._data = OrderedDict()      # key -> (value, expires_at or None)
        self._hits = 0
        self._misses = 0
        self._expired = 0
        self._lock = threading.Lock()

    def _is_expired(self, expires_at):
        return expires_at is not None and self._timer() >= expires_at

    def get(self, key, default=None):
        """Return the value for key, marking it as most recently used."""
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                self._misses += 1
                return default
            value, expires_at = entry
            if self._is_expired(expires_at):
                del self._data[key]
                self._expired += 1
                self._misses += 1
                return default
            self._hits += 1
            self._data.move_to_end(key)
            return value

    def put(self, key, value, ttl=_MISSING := object()):
        """Insert or update key. ttl overrides default_ttl; None means no expiry."""
        with self._lock:
            if ttl is LRUCache._sentinel:
                ttl = self.default_ttl
            elif ttl is not None and ttl <= 0:
                raise ValueError("ttl must be positive or None")
            expires_at = None if ttl is None else self._timer() + ttl
            if key in self._data:
                self._data.move_to_end(key)
            self._data[key] = (value, expires_at)
            if len(self._data) > self.capacity:
                self._evict_locked()

    def _evict_locked(self):
        """Drop an expired entry if one is at hand, else the least recently used."""
        for k, (_, expires_at) in list(self._data.items()):
            if self._is_expired(expires_at):
                del self._data[k]
                self._expired += 1
                if len(self._data) <= self.capacity:
                    return
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def purge(self):
        """Drop every expired entry; returns how many were removed."""
        with self._lock:
            stale = [k for k, (_, e) in self._data.items() if self._is_expired(e)]
            for k in stale:
                del self._data[k]
            self._expired += len(stale)
            return len(stale)

    def stats(self):
        """Return hit/miss/expiry counts and current size."""
        with self._lock:
            return {
                "hits": self._hits,
                "misses": self._misses,
                "expired": self._expired,
                "size": len(self._data),
            }

    def __contains__(self, key):
        with self._lock:
            entry = self._data.get(key)
            return entry is not None and not self._is_expired(entry[1])

    def __len__(self):
        """Number of stored entries, including any not yet reaped."""
        with self._lock:
            return len(self._data)

    def __repr__(self):
        with self._lock:
            return (f"LRUCache(capacity={self.capacity}, "
                    f"default_ttl={self.default_ttl}, size={len(self._data)})")


LRUCache._sentinel = object()


if __name__ == "__main__":
    cache = LRUCache(2, default_ttl=0.05)
    cache.put("a", 1)
    cache.put("b", 2, ttl=None)   # never expires
    print(cache.get("a"))         # 1
    time.sleep(0.06)
    print(cache.get("a"))         # None -- expired
    print(cache.get("b"))         # 2
    print(cache.stats())          # {'hits': 2, 'misses': 1, 'expired': 1, 'size': 1}
```

One fix to make before you run it: the `ttl=_MISSING := object()` default in `put` is wrong — a walrus in a default evaluates once at class-definition time and leaks the name. Use the module-level sentinel instead:

```python
_MISSING = object()

    def put(self, key, value, ttl=_MISSING):
        ...
        if ttl is _MISSING:
            ttl = self.default_ttl
```

and drop the trailing `LRUCache._sentinel = object()` line.

Two design notes. Expiry is lazy — an entry is only removed when you touch it, `_evict_locked` sweeps for one, or you call `purge()`; nothing runs in the background, so `__len__` can count entries that are already dead. `timer` defaults to `time.monotonic` rather than `time.time` so TTLs survive a wall-clock adjustment; pass a fake timer in tests to avoid `sleep`.

