from collections import OrderedDict


class LRUCache:
    """A capacity-bounded cache that evicts the stalest entry once it fills.

    Retrievals count as uses exactly like stores do, so each successful lookup
    shifts that key to the freshest end of the OrderedDict below.
    """

    __slots__ = ("capacity", "_data")

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        """Return whatever `key` maps to and flag it as the freshest use."""
        if key not in self._data:
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Record `key`, evicting the stalest entry once capacity is exceeded."""
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __contains__(self, key):
        # A membership check is a pure look; recency order is left alone.
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        items = ", ".join(f"{k!r}: {v!r}" for k, v in self._data.items())
        return f"LRUCache(capacity={self.capacity}, {{{items}}})"
