  * Exception from the callback  -> logged, routed to on_error, worker continues.
  * BaseException                -> recorded, worker exits, backlog released.
  * Failure inside the failure   -> swallowed; nothing may unwind _run silently.
"""

import logging
import queue
import threading
import time

log = logging.getLogger(__name__)

_POLL = 0.1          # how often a blocked producer re-checks worker liveness
OVERFLOW_POLICIES = ("block", "drop_newest", "drop_oldest")


class _Sentinel:
