        The sentinel bypasses the admission window, so this never blocks on a
        full worker -- but it still queues *behind* the backlog, so pending
        items are processed first.
        """
        with self._lock:
            if not self._started:
                return
            already, self._stopping = self._stopping, True
        if not already and not self.stopped.is_set():
            self.queue.put(self.sentinel)
        if wait:
            self._thread.join(timeout)

